const {test}=require('node:test'),a=require('node:assert/strict'),L=require('./web/lunar');
// Independently published NASA/GSFC UT phase table; never generated by the code under test.
// https://eclipse.gsfc.nasa.gov/phase/phases2001.html retrieved 2026-11-10.
const nasa=['2024-04-23T23:49Z','2024-05-23T13:53Z','2024-10-17T11:26Z','2026-01-03T10:03Z','2026-02-01T22:09Z','2026-03-03T11:38Z','2026-04-02T02:12Z','2026-05-01T17:23Z','2026-05-31T08:45Z','2026-06-29T23:57Z','2026-07-29T14:36Z','2026-08-28T04:18Z','2026-09-26T16:49Z','2026-10-26T04:12Z','2026-11-24T14:53Z','2026-12-24T01:28Z'];
for(const published of nasa)test('offline full moon agrees within two minutes with NASA UT '+published,()=>{const t=Date.parse(published),near=L.moons(t).sort((a,b)=>Math.abs(a-t)-Math.abs(b-t))[0];a.ok(Math.abs(near-t)<120000,'error seconds '+Math.abs(near-t)/1000);});
test('full moon follows local date, including two full moons in May and Honolulu previous date',()=>{const C=require('./web/calendar'),key=z=>t=>C.key(C.parts(t,z));a.equal(L.view(Date.parse('2026-08-27T20:00Z'),key('Pacific/Honolulu')).fullMoon,true);a.equal(L.view(Date.parse('2026-08-27T20:00Z'),key('UTC')).fullMoon,false);a.equal(L.view(Date.parse('2026-05-31T10:00Z'),key('UTC')).fullMoon,true);a.equal(L.view(Date.parse('2026-05-01T10:00Z'),key('UTC')).fullMoon,true);});
test('range is explicit, finite and deterministic; callers cannot mutate cached moons',()=>{a.equal(L.view(Date.parse('1900-01-01'),()=>'' ).lunarSupported,false);const t=Date.parse('2026-10-26'),x=L.moons(t);x.length=0;a.ok(L.moons(t).length>0);a.deepEqual(L.view(t,t=>new Date(t).toISOString().slice(0,10)),L.view(t,t=>new Date(t).toISOString().slice(0,10)));});
